const chatForm = document.getElementById("chatForm");
const promptInput = document.getElementById("promptInput");
const messages = document.getElementById("messages");
const sendButton = document.getElementById("sendButton");
const statusText = document.getElementById("statusText");
const clearButton = document.getElementById("clearButton");

// Read the CSRF token generated by Django
function getCSRFToken() {
  const input = document.querySelector('[name="csrfmiddlewaretoken"]');

  return input ? input.value : "";
}

// Display a message in the conversation
function addMessage(role, text) {
  const message = document.createElement("div");
  message.className = "message " + role;

  const label = document.createElement("strong");
  label.textContent = role === "user" ? "YOU" : "AI ASSISTANT";

  const content = document.createElement("p");
  content.textContent = text;

  message.appendChild(label);
  message.appendChild(content);

  messages.appendChild(message);
  messages.scrollTop = messages.scrollHeight;
}

// Send the prompt to Django
chatForm.addEventListener("submit", async function (event) {
  event.preventDefault();

  const prompt = promptInput.value.trim();

  if (!prompt) {
    return;
  }

  addMessage("user", prompt);

  promptInput.value = "";
  sendButton.disabled = true;
  statusText.textContent = "Gemini is thinking...";

  try {
    const response = await fetch("/api/chat/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-CSRFToken": getCSRFToken(),
      },
      body: JSON.stringify({
        prompt: prompt,
      }),
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error || "Something went wrong.");
    }

    addMessage("assistant", data.answer);
  } catch (error) {
    addMessage("assistant", "Error: " + error.message);
  } finally {
    sendButton.disabled = false;
    statusText.textContent = "Ready to help";
    promptInput.focus();
  }
});

// Fill the input when a suggested question is clicked
document.querySelectorAll(".suggestion").forEach(function (button) {
  button.addEventListener("click", function () {
    promptInput.value = button.dataset.prompt;
    promptInput.focus();
  });
});

// Clear the conversation
clearButton.addEventListener("click", function () {
  messages.replaceChildren();

  addMessage("assistant", "Chat cleared! What would you like to learn?");
});

// Register the service worker (we will create it in Part 3)
if ("serviceWorker" in navigator) {
  window.addEventListener("load", function () {
    navigator.serviceWorker
      .register("/service-worker.js")
      .catch(function (error) {
        console.error("Service worker registration failed:", error);
      });
  });
}
